import React from "react";
import { Link } from "react-router-dom";

export default function Dashboard() {

const user = JSON.parse(
localStorage.getItem("user")
);

const role = user?.role || "Student";

let cards = [];

if(role==="Admin"){

cards=[

{

title:"👨‍🎓 Manage Students",

path:"/students",

color:"#2563eb"

},

{

title:"👨‍🏫 Manage Instructors",

path:"/instructors",

color:"#7c3aed"

},

{

title:"📚 Courses",

path:"/courses",

color:"#16a34a"

},

{

title:"⚙️ Settings",

path:"/settings",

color:"#ef4444"

}

];

}

else if(role==="Instructor"){

cards=[

{

title:"📚 My Courses",

path:"/courses",

color:"#2563eb"

},

{

title:"👨‍🎓 Students",

path:"/students",

color:"#16a34a"

},

{

title:"⚙️ Settings",

path:"/settings",

color:"#ef4444"

}

];

}

else{

cards=[

{

title:"👤 Profile",

path:"/profile",

color:"#2563eb"

},

{

title:"📚 Courses",

path:"/courses",

color:"#16a34a"

},

{

title:"📈 Progress",

path:"/progress",

color:"#f59e0b"

}

];

}

return(

<div

style={{

minHeight:"100vh",

background:

"linear-gradient(135deg,#0f172a,#1e293b,#334155)",

padding:"40px"

}}

>

<h1

style={{

textAlign:"center",

color:"white",

fontSize:"45px"

}}

>

RBAC Dashboard

</h1>

<p

style={{

textAlign:"center",

color:"#cbd5e1",

marginBottom:"40px"

}}

>

Welcome

{

user ?

" "+user.name

:

" User"

}

</p>

<div

style={{

display:"grid",

gridTemplateColumns:

"repeat(auto-fit,minmax(280px,1fr))",

gap:"25px"

}}

>

{

cards.map((card,index)=>(

<Link

key={index}

to={card.path}

style={{

textDecoration:"none"

}}

>

<div

style={{

background:card.color,

padding:"30px",

borderRadius:"20px",

color:"white",

boxShadow:

"0 10px 20px rgba(0,0,0,0.2)"

}}

>

<h2>

{card.title}

</h2>

<p>

Open

{

card.title.replace(

/[^a-zA-Z ]/g,

""

)

}

</p>

</div>

</Link>

))

}

</div>

</div>

)

}
